    worked: [{ title: "Course VC example", formula: "% predicted = corrected measured VC / predicted VC × 100", working: "2500 mL × 1.1 = 2750 mL. 2750/3410 × 100 = 80.6%, approximately 81%, within the course’s stated band." }, { title: "Volume and ratio drill", formula: "VC = IRV + TV + ERV; FEV1/FVC × 100", working: "IRV 2.0 L + TV 0.5 L + ERV 1.0 L = VC 3.5 L. If forced FEV1 is 2.4 L and FVC 3.0 L, their ratio is 80%. Do not mix litres and millilitres." }],
    recall: [recall("What cannot basic spirometry measure?", "Residual volume, and therefore capacities containing it: FRC and TLC."), recall("Which seven values are requested in slide 24?", "TV, IRV, ERV, VC, VC/predicted VC%, FEV1 and FEV1/FVC%, followed by a judgement about lung tissue/airway resistance."), recall("Why might an early stop be misleading?", "It can underestimate FVC and distort the ratio; assess quality before interpreting physiology.")],
    images: [image("spirometry-calibration", "How this course calibrates its tracing", "Spirometry slide 21", "Identify the one-second interval and the 100-cc volume spacing before reading excursions."), image("spirometry-exercise", "The actual course calculation assignment", "Spirometry slide 24", "Female, 24 years, height 158 cm, temperature 22°C. Use the provided prediction table; explain your endpoints. No invented precise answer is supplied for this low-resolution trace.")],
    videos: [video("M4C8EInOMOI", "Peak flow and spirometry", "Oxford Medical Education", "Focus on the spirometry manoeuvre. Peak flow is supplementary; the local pack’s calculation exercise is essential.")],
    questions: [
      q("manoeuvre", 0, "Which event is most likely to invalidate measurement of FEV1?", "A cough during the first second", "A cough interrupts the first-second forced expiration and can distort the measurement.", [["A tight mouth seal", "A tight seal is desirable."], ["Maximal inspiration before blowing", "This is needed for the standard manoeuvre."], ["A rapid start to expiration", "A good rapid start is desirable."]], "6, 17–23"),
      q("early-stop", 0, "A subject stops forced expiration early. Which concern should be addressed before interpreting the result?", "FVC may be underestimated because the manoeuvre is incomplete", "A low recorded FVC may reflect poor performance rather than reduced lung size.", [["TLC has been measured directly", "Basic spirometry does not directly measure TLC."], ["The result proves fibrosis", "A poor manoeuvre cannot establish a disease diagnosis."], ["The nose clip makes the result invalid", "A nose clip is part of the usual procedure."]], "6, 22–24"),
      q("rv", 1, "Which volume cannot be measured directly by simple spirometry?", "Residual volume", "Residual gas remains in the lungs after maximal expiration and is not collected by simple spirometry.", [["Tidal volume", "Quiet-breathing excursion can be measured."], ["Expiratory reserve volume", "Additional expired volume can be measured."], ["Vital capacity", "The maximal movable volume can be measured."]], "7–9, 23–24"),
      q("vc", 1, "TV is 500 mL, IRV is 2000 mL and ERV is 1000 mL. What is VC?", "3500 mL", "Vital capacity includes all three movable volumes: VC = TV + IRV + ERV = 500 + 2000 + 1000 = 3500 mL. Residual volume is not included.", [["2500 mL", "This adds IRV and TV but omits the additional 1000 mL of ERV."], ["1500 mL", "This adds TV and ERV but omits the additional 2000 mL of IRV."], ["4500 mL", "No additional 1000 mL is supplied or required."]], "7–9, 24"),
      q("correction", 2, "The course exercise supplies measured VC 2500 mL and correction factor 1.1. What is corrected VC?", "2750 mL", "Multiply 2500 × 1.1. The factor is given for this exercise, not every spirometry test.", [["2273 mL", "This divides by the factor instead of multiplying."], ["2501.1 mL", "The correction is multiplicative, not additive."], ["3410 mL", "3410 is the predicted value in the worked example, not corrected measured VC."]], "10–16"),
      q("predicted", 2, "Corrected measured VC is 2750 mL and predicted VC is 3410 mL. What is percentage predicted?", "About 81%", "2750/3410 × 100 = 80.6%, rounded to 81%.", [["About 124%", "This reverses measured and predicted values."], ["About 66%", "This does not follow the supplied ratio."], ["About 8%", "This is a decimal-place error."]], "16"),
      q("ratio", 3, "FEV1 is 1.8 L and FVC is 3.0 L after an acceptable manoeuvre. What is FEV1/FVC?", "60%", "1.8/3.0 × 100 = 60%. The ratio compares volumes in the same units.", [["167%", "This reverses numerator and denominator."], ["1.2%", "1.2 L is the volume difference, not the percentage ratio."], ["90%", "This would require a different denominator."]], "20–24"),
      q("restriction", 3, "A technically acceptable trace shows low FVC with a preserved FEV1/FVC ratio. What is the most defensible conclusion?", "Possible restrictive pattern; confirm with lung-volume measurement", "Spirometry can suggest restriction but cannot establish low TLC by itself.", [["Restriction is proven by direct TLC measurement", "TLC has not been directly measured by spirometry."], ["Definite obstruction solely because FVC is low", "Obstruction is assessed using the ratio and clinical/reference context."], ["Normal lung function is guaranteed", "A low FVC still needs evaluation."]], "22–24; interpretation limitation"),
    ],
